          "found = set()\n"
          "for i, (db, r) in enumerate(databases.items(), 1):\n"
          "    hits = {p for p in relevant if rng.random() < r}\n"
          "    found |= hits\n"
          "    print(f'{i} дерекқор (+{db}): табылды {len(found)}/40, теория {40 * (1 - __import__(\"math\").prod(1 - x for x in list(databases.values())[:i])):.1f}')\n\n"
          "# Дереккөзді бағалау: жариялану түрі, рецензия, қайталанатындық\n"
