RAND = ("import random\n\n"
        "rng = random.Random(3)\n"
        "# Әр оқушының «ынтасы» (бақыланбайтын) нәтижеге де, жаңа әдісті таңдауға да әсер етеді\n"
        "students = [rng.gauss(0, 1) for _ in range(2000)]\n"
        "TRUE_EFFECT = 2.0                               # жаңа әдістің шын әсері (ұпай)\n\n"
        "def outcome(motivation, treated):\n"
        "    return 60 + 8 * motivation + (TRUE_EFFECT if treated else 0) + rng.gauss(0, 5)\n\n"
        "def estimate(assign):\n"
        "    t = [outcome(m, True) for m, a in zip(students, assign) if a]\n"
        "    c = [outcome(m, False) for m, a in zip(students, assign) if not a]\n"
        "    mt = sum(m for m, a in zip(students, assign) if a) / len(t)\n"
        "    mc = sum(m for m, a in zip(students, assign) if not a) / len(c)\n"
        "    return sum(t) / len(t) - sum(c) / len(c), mt - mc\n\n"
        "self_selected = [m + rng.gauss(0, 0.5) > 0.3 for m in students]     # ынталылар өздері таңдайды\n"
        "randomized = [rng.random() < 0.5 for _ in students]\n"
        "for name, assign in [('өз еркімен таңдау', self_selected), ('рандомизация', randomized)]:\n"
        "    eff, gap = estimate(assign)\n"
        "    print(f'{name:18}: бағаланған әсер {eff:5.2f} (шындық {TRUE_EFFECT}), топтардың ынта айырмасы {gap:+.2f}')")

