BENCH = ("import random, statistics\n\n"
         "rng = random.Random(2)\n\n"
         "def measure(true_ms):\n"
         "    \"\"\"өлшеу моделі: шын уақыт + жүйе шуы + сирек үлкен кедергі (басқа процесс)\"\"\"\n"
         "    noise = rng.gauss(0, 0.8)\n"
         "    spike = 15 if rng.random() < 0.05 else 0\n"
         "    return true_ms + noise + spike\n\n"
         "A, B = 10.0, 10.6                         # шын уақыттар: B 6% баяу\n"
         "for n in (1, 5, 30):\n"
         "    a = [measure(A) for _ in range(n)]\n"
         "    b = [measure(B) for _ in range(n)]\n"
         "    print(f'n = {n:2}: орташа A {statistics.mean(a):6.2f}, B {statistics.mean(b):6.2f} | медиана A {statistics.median(a):6.2f}, B {statistics.median(b):6.2f}')\n\n"
         "sd1 = statistics.pstdev([measure(A) for _ in range(800)])\n"
         "means = [sum(measure(A) for _ in range(25)) / 25 for _ in range(120)]\n"
         "print(f'бір өлшеудің σ ≈ {sd1:.2f}, 25 өлшем орташасының σ ≈ {statistics.pstdev(means):.2f} (теория σ/5 = {sd1 / 5:.2f})')")

