BOOT = ("import random, statistics\n\n"
        "rng = random.Random(5)\n"
        "gains = [round(rng.gauss(3.0, 6.0), 1) for _ in range(40)]     # 40 оқушының ұпай өсімі\n"
        "obs = statistics.mean(gains)\n\n"
        "B = 1000\n"
        "boot = sorted(sum(rng.choices(gains, k=len(gains))) / len(gains) for _ in range(B))\n"
        "lo, hi = boot[int(0.025 * B)], boot[int(0.975 * B) - 1]\n"
        "print(f'бақыланған орташа өсім: {obs:.2f}')\n"
        "print(f'95% бутстрэп интервалы: [{lo:.2f}, {hi:.2f}]')\n"
        "se = statistics.stdev(gains) / len(gains) ** 0.5\n"
        "print(f'қалыпты жуықтау: [{obs - 1.96 * se:.2f}, {obs + 1.96 * se:.2f}]')\n\n"
        "# Бір бақылаудың бутстрэп үлгісіне кірмеу ықтималдығы\n"
        "n = len(gains)\n"
        "missing = sum(0 not in rng.choices(range(n), k=n) for _ in range(3000)) / 3000\n"
        "print(f'бақылау №0 үлгіде жоқ: {missing:.3f}, теория (1 − 1/n)^n = {(1 - 1 / n) ** n:.3f}, шегі 1/e = {1 / 2.718281828:.3f}')")

